L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "疫病に感染し、魂が墜ちてしまった妖精は悪魔となる。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Fairies tainted by the plague become devils."
