L21_1.m_Pos = "L"
L22_1 = "그리고 황금나무의 가능성을 대신해, 인간의 가능성을 <color=#ffd34c>양분</color>으로 삼게 되지."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そして黄金の木から受け取っていた可能性の代わりとして、人間の可能性を<color=#ffd34c>養分</color>とするようになるのよ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Thus, instead of the Golden Tree's possibilities, they use humans' possibilities as their <color=#ffd34c>nutrition</color>."
L21_1.m_Talk_ENG = L22_1
L22_1 = "它們不再以黃金樹的可能性為<color=#ffd34c>養分</color>，轉而以人類的可能性為食。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "它们不再以黄金树的可能性为<color=#ffd34c>养分</color>，转而以人类的可能性为食。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Thus, instead of the Golden Tree's possibilities, they use humans' possibilities as their <color=#ffd34c>nutrition</color>."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Thus, instead of the Golden Tree's possibilities, they use humans' possibilities as their <color=#ffd34c>nutrition</color>."
L21_1.m_Talk_FRA = L22_1
