L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_DESPAIR"
L24_1.m_Face = L25_1
L24_1.m_CharStrID = "MORDRED_ROOT_NULL_LU"
L24_1.m_Pos = "R"
L25_1 = "역사서에도, 동화책에서도, 소원을 들어주는 아발론의 일곱 요정에 대한 언급은 있었지만…"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "歴史書やおとぎ話には、願いを叶えてくれるアバロンの七人の妖精についての記述はあっても……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "In history books and tales, there were only mentions of the seven wish-granting fairies from Avalon..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "無論是歷史書或童話書中，都有提到阿瓦隆有的七個可以實現願望的精靈…"
L24_1.m_Talk_TWN = L25_1
L25_1 = "无论是历史书还是童话书，都提到了古阿瓦隆能实现愿望的七个精灵……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "In history books and tales, there were only mentions of the seven wish-granting fairies from Avalon..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "In history books and tales, there were only mentions of the seven wish-granting fairies from Avalon..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "AVENGER_ACT2_INTERLUDE1@75#Talk"
