L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "MORDRED_ROOT_NULL_LU"
L25_1.m_Pos = "R"
L26_1 = "그 행방을 찾는 건 엘리시온에서 금기였거든요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "その行方を探す行為は、エリシオンでは禁忌とされているんです。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "but searching for their whereabouts was forbidden in Elysion."
L25_1.m_Talk_ENG = L26_1
L26_1 = "但在艾利森，卻禁止我們尋找精靈的下落。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "但在艾路绅，寻找他们的下落却是禁忌。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "but searching for their whereabouts was forbidden in Elysion."
L25_1.m_Talk_DEU = L26_1
L26_1 = "but searching for their whereabouts was forbidden in Elysion."
L25_1.m_Talk_FRA = L26_1
