L28_1 = "알고 있더라도 굳이 그런 사실을 퍼트리진 않았을 거야."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "仮にそうだとしても、それを公表するようなことはしなかったと思うわ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Even if they did, they would not have let the public know."
L27_1.m_Talk_ENG = L28_1
L28_1 = "就算真的知道，他們也不會刻意讓事實散布出去。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "即使知道，他们也不会刻意传播这种事实。"
