L29_1 = "조금이라도 더 많은 희망이 필요한 시기에, 소원을 들어주는 요정의 존재를 부정하려는 인간은 없을 테니까."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "儚い希望でさえすがりつきたいこの時代において、願いを叶えてくれる妖精の存在を否定するような人間はいないからね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "In a time when hope is needed most, there would be no human who would deny the existence of fairies."
L28_1.m_Talk_ENG = L29_1
L29_1 = "因為在這個需要更多希望的時代，大家都希望精靈是真實存在的。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "因为在需要更多希望的时代，没有人会否定能实现愿望的精灵的存在。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "In a time when hope is needed most, there would be no human who would deny the existence of fairies."
L28_1.m_Talk_DEU = L29_1
L29_1 = "In a time when hope is needed most, there would be no human who would deny the existence of fairies."
