L31_1 = "그럼 이 세계의 요정들은… 전부 악마가 된 걸까요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "じゃあ、この世界の妖精はすべて……悪魔となってしまったのでしょうか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Then, are all the fairies of this world... now devils?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "所以這個世界的精靈…全都變成魔鬼了嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "那么，这个世界的精灵们……已经全都变成恶魔了吗？"
