L7_1 = "동토 바깥은 이미 오래전에 사람이 살 수 없는 곳이 됐다고 했어요! 그런 곳에서 왔다면 평범한 인간일 리 없잖아요!"
L6_1.m_Talk_KOREA = L7_1
