L3_1 = "장터가 항상 이렇게 성대하진 않아. 지금은 땅이 열매를 맺는 수확절이라 나름 풍족하거든."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "商店が常にこんなに活気があるわけじゃないよ。今は果物の収穫時期だから、食材が豊富なの。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The market isn't always as grand as it is now. But it's harvesting season, so we are in abundance."
L2_1.m_Talk_ENG = L3_1
L3_1 = "市場平時也沒這麼熱鬧，但現在是豐收季，所以比較豐富一點。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "平时的集市也不会这么热闹。但现在是土地结出果实的收获季节，所以比较丰盛。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "The market isn't always as grand as it is now. But it's harvesting season, so we are in abundance."
L2_1.m_Talk_DEU = L3_1
L3_1 = "The market isn't always as grand as it is now. But it's harvesting season, so we are in abundance."
L2_1.m_Talk_FRA = L3_1
