L5_1 = "AVENGER_ACT2_INTERLUDE1@204#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 6600201
