L4_1.m_Pos = "R"
L5_1 = "그야 당연하잖아. 연중 대부분은 추위 때문에 싹도 자라지 못한다고."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そりゃ当然でしょ。一年のほとんどは寒さのせいで芽も生えないんだからね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Of course. It's cold for most of the year which hinders the growth of sprouts."
L4_1.m_Talk_ENG = L5_1
L5_1 = "你在說什麼廢話，因為大部分的時候都很寒冷，連芽都發不出來。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "你在说什么废话。大部分时间因为寒冷，连芽都长不出来。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Of course. It's cold for most of the year which hinders the growth of sprouts."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Of course. It's cold for most of the year which hinders the growth of sprouts."
L4_1.m_Talk_FRA = L5_1
