L6_1 = "몰랐어요. 엘리시온에선 과일이라면 언제든 구할 수 있었거든요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "そうだったんですか。エリシオンでは果物ならいつでも手に入るんですよ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "I didn't know. We could always find fruit in Elysion."
L5_1.m_Talk_ENG = L6_1
L6_1 = "原來是這樣，因為在艾利森隨時都買得到水果。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "我……不知道……在艾路绅，随时都可以买到水果。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "I didn't know. We could always find fruit in Elysion."
L5_1.m_Talk_DEU = L6_1
