L7_1 = "자랑하지 마! 그루터기도 내가 태어나기 전엔 사계절이 멀쩡해서 과일이 아주 풍족했거든?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "自慢しているの？　切り株だってあたしが生まれる前は四季がちゃんとあったから、果物がたくさん採れてたわよ！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Stop bragging! The Stump also had four seasons and had plenty of fruit before I was born too!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "哼，這是在炫耀嗎！我出生以前氣候也很正常，那時候木墩的水果也是很豐富的！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "哼，少得意了！在我出生前，四季正常的时候，树桩的水果也是很丰富的！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Stop bragging! The Stump also had four seasons and had plenty of fruit before I was born too!"
